// Imagenes del membrete (logo y franja de bandera) embebidas en base64 para incrustarlas en el PDF.
// Igual que con las fuentes (ver fonts-zt-nature.js): NO se cargan con new Image()+canvas.toDataURL() porque
// Chrome tainea el canvas al leer imagenes cargadas desde file://, incluso siendo del mismo directorio,
// y la app tiene que poder abrirse con doble clic via file://. bandera-pdf.png es bandera.svg rasterizado
// una vez a ~300dpi (2480x104px) para poder incrustarlo como imagen (jsPDF no soporta SVG vectorial).
window.PDF_IMAGENES = window.PDF_IMAGENES || {};
window.PDF_IMAGENES.logo = "data:image/png;base64,";
window.PDF_IMAGENES.bandera = "data:image/png;base64,";